import { Typography, Box } from '@mui/material';
import { TOKENS } from '../../tokens';

const SectionLabel = ({ children, sx = {} }) => (
  <Typography
    component="span"
    sx={{
      display: 'inline-flex',
      alignItems: 'center',
      gap: 1.5,
      fontSize: TOKENS.typography.label,
      fontWeight: 600,
      letterSpacing: '0.18em',
      textTransform: 'uppercase',
      color: TOKENS.colors.violet,
      mb: 2,
      ...sx,
    }}
  >
    <Box
      component="span"
      sx={{
        width: 20,
        height: 2,
        borderRadius: 1,
        bgcolor: TOKENS.colors.lime,
      }}
    />
    {children}
  </Typography>
);

export const SectionHeading = ({ label, title, titleAccent, subtitle, align = 'left', sx = {} }) => (
  <Box
    sx={{
      textAlign: align,
      maxWidth: align === 'center' ? 640 : 560,
      mx: align === 'center' ? 'auto' : 0,
      mb: TOKENS.section.headingMb,
      ...sx,
    }}
  >
    {label && (
      <Box sx={{ display: 'flex', justifyContent: align === 'center' ? 'center' : 'flex-start' }}>
        <SectionLabel>{label}</SectionLabel>
      </Box>
    )}
    <Typography
      variant="h2"
      sx={{
        color: TOKENS.colors.textPrimary,
        mb: subtitle ? 1.5 : 0,
        fontFamily: TOKENS.fonts.display,
      }}
    >
      {title}
      {titleAccent && (
        <Box component="span" sx={{ color: TOKENS.colors.violet, display: 'block' }}>
          {titleAccent}
        </Box>
      )}
    </Typography>
    {subtitle && (
      <Typography
        variant="body1"
        sx={{ color: TOKENS.colors.textSecondary, lineHeight: 1.7, maxWidth: 500, mx: align === 'center' ? 'auto' : 0 }}
      >
        {subtitle}
      </Typography>
    )}
  </Box>
);

export default SectionLabel;
