import { forwardRef } from 'react';
import { Box } from '@mui/material';
import { TOKENS } from '../../tokens';

const GlassSurface = forwardRef(({
  children,
  hover = true,
  strong = false,
  sx = {},
  className,
  ...rest
}, ref) => (
  <Box
    ref={ref}
    className={className}
    sx={{
      background: strong ? TOKENS.glass.backgroundStrong : TOKENS.glass.background,
      backdropFilter: TOKENS.glass.blur,
      WebkitBackdropFilter: TOKENS.glass.blur,
      border: `1px solid ${TOKENS.colors.border}`,
      borderRadius: TOKENS.radius.lg,
      transition: TOKENS.transition,
      ...(hover && {
        '&:hover': {
          transform: 'translateY(-6px)',
          borderColor: TOKENS.colors.borderHover,
          boxShadow: `0 16px 48px rgba(15, 23, 42, 0.1), 0 0 0 1px ${TOKENS.colors.borderHover}`,
        },
      }),
      ...sx,
    }}
    {...rest}
  >
    {children}
  </Box>
));

GlassSurface.displayName = 'GlassSurface';

export default GlassSurface;
