import { useEffect, useState } from 'react';
import { Box, Typography } from '@mui/material';
import DownloadRoundedIcon from '@mui/icons-material/DownloadRounded';
import { Link } from 'react-router-dom';
import GlowButton from '../ui/GlowButton';
import { APP_STORE_URL } from '../../constants/plans';
import { TOKENS } from '../../tokens';

const HEADER_HEIGHT = { xs: 60, sm: 64, md: 72 };

const Navbar = ({ lightWhenTop = false }) => {
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 16);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  const lightNav = lightWhenTop && !scrolled;

  return (
    <Box
      component="header"
      sx={{
        position: 'fixed',
        top: 0,
        left: 0,
        right: 0,
        zIndex: 1200,
        height: HEADER_HEIGHT,
        display: 'flex',
        alignItems: 'center',
        bgcolor: scrolled ? TOKENS.glass.backgroundStrong : 'transparent',
        backdropFilter: scrolled ? TOKENS.glass.blur : 'none',
        WebkitBackdropFilter: scrolled ? TOKENS.glass.blur : 'none',
        borderBottom: scrolled ? `1px solid ${TOKENS.colors.border}` : '1px solid transparent',
        transition: TOKENS.transition,
      }}
    >
      <Box
        sx={{
          width: '100%',
          px: {
            xs: `${TOKENS.layout.gutter.xs}px`,
            sm: `${TOKENS.layout.gutter.sm}px`,
            lg: `${TOKENS.layout.gutter.lg}px`,
          },
          height: '100%',
          display: 'flex',
          flexDirection: 'row',
          flexWrap: 'nowrap',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: { xs: 1, sm: 1.5, md: 3 },
        }}
      >
        {/* Logo */}
        <Box
          component={Link}
          to="/signup-landingpage"
          sx={{
            display: 'flex',
            flexDirection: 'row',
            flexWrap: 'nowrap',
            alignItems: 'center',
            gap: { xs: 0.75, sm: 1, md: 1.25 },
            textDecoration: 'none',
            flex: '1 1 auto',
            minWidth: 0,
            maxWidth: { xs: 'calc(100% - 108px)', sm: 'calc(100% - 148px)', md: 'none' },
            overflow: 'hidden',
          }}
        >
          <Box
            component="img"
            src="/favicon.svg"
            alt="Savage Mushroom"
            sx={{
              width: { xs: 36, sm: 42, md: 50 },
              height: { xs: 36, sm: 42, md: 50 },
              flexShrink: 0,
            }}
          />
          <Typography
            sx={{
              fontFamily: TOKENS.fonts.display,
              fontWeight: 700,
              fontSize: { xs: '0.8125rem', sm: '1rem', md: '1.25rem' },
              color: lightNav ? TOKENS.colors.textOnImage : TOKENS.colors.textPrimary,
              letterSpacing: '-0.02em',
              whiteSpace: 'nowrap',
              overflow: 'hidden',
              textOverflow: 'ellipsis',
              minWidth: 0,
            }}
          >
            Savage Mushroom
          </Typography>
        </Box>

        {/* CTA */}
        <GlowButton
          href={APP_STORE_URL}
          size="small"
          startIcon={
            <DownloadRoundedIcon sx={{ fontSize: { xs: 16, sm: 18, md: 20 } }} />
          }
          sx={{
            flex: '0 0 auto',
            flexShrink: 0,
            px: { xs: 1.5, sm: 2, md: 2.5, lg: 3 },
            py: { xs: 0.75, sm: 1 },
            minHeight: { xs: 36, sm: 38, md: 40, lg: 44 },
            fontSize: { xs: '0.75rem', sm: '0.875rem', md: TOKENS.typography.nav },
            whiteSpace: 'nowrap',
            '& .MuiButton-startIcon': {
              mr: { xs: 0.5, sm: 0.75 },
              ml: { xs: -0.25, sm: 0 },
            },
          }}
        >
          <Box component="span" sx={{ display: { xs: 'inline', sm: 'none' } }}>
            Download
          </Box>
          <Box component="span" sx={{ display: { xs: 'none', sm: 'inline' } }}>
            Download Now
          </Box>
        </GlowButton>
      </Box>
    </Box>
  );
};

export default Navbar;
