import { useCallback, useEffect, useRef, useState } from 'react';
import { Box, Typography } from '@mui/material';
import { useReveal } from '../../hooks/useReveal';
import { TOKENS } from '../../tokens';

const HandleIcon = () => (
  <svg viewBox="0 0 22 22" fill="none" width="22" height="22" aria-hidden>
    <path
      d="M8 6l-4 5 4 5"
      stroke="#0d0d0d"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
    />
    <path
      d="M14 6l4 5-4 5"
      stroke="#0d0d0d"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
    />
  </svg>
);

const BeforeAfterCard = ({ beforeImage, afterImage, initialPosition, name, result, meta, id, index = 0 }) => {
  const [position, setPosition] = useState(initialPosition);
  const cardRef = useRef(null);
  const revealRef = useReveal(0.08);
  const draggingRef = useRef(false);

  const setPositionFromClientX = useCallback((clientX) => {
    const rect = cardRef.current?.getBoundingClientRect();
    if (!rect) return;
    const next = ((clientX - rect.left) / rect.width) * 100;
    setPosition(Math.min(100, Math.max(0, next)));
  }, []);

  useEffect(() => {
    const onPointerMove = (event) => {
      if (!draggingRef.current) return;
      setPositionFromClientX(event.clientX);
    };

    const onPointerUp = () => {
      draggingRef.current = false;
    };

    window.addEventListener('pointermove', onPointerMove);
    window.addEventListener('pointerup', onPointerUp);

    return () => {
      window.removeEventListener('pointermove', onPointerMove);
      window.removeEventListener('pointerup', onPointerUp);
    };
  }, [setPositionFromClientX]);

  const startDrag = (event) => {
    draggingRef.current = true;
    setPositionFromClientX(event.clientX);
  };

  const clipRight = 100 - position;

  return (
    <Box ref={revealRef} className={`reveal reveal-delay-${index + 1}`} sx={{ width: '100%', minWidth: 0 }}>
      <Box
        ref={cardRef}
        onPointerDown={startDrag}
        sx={{
          position: 'relative',
          width: '100%',
          aspectRatio: '3 / 4',
          borderRadius: TOKENS.radius.lg,
          overflow: 'hidden',
          cursor: 'ew-resize',
          userSelect: 'none',
          touchAction: 'none',
          bgcolor: TOKENS.colors.surface,
          boxShadow: TOKENS.card.shadow,
          border: `1px solid ${TOKENS.colors.border}`,
        }}
      >
        <Box
          aria-hidden
          sx={{
            position: 'absolute',
            inset: 0,
            backgroundImage: `url(${beforeImage})`,
            backgroundSize: 'cover',
            backgroundPosition: 'center',
          }}
        />

        <Box
          aria-hidden
          sx={{
            position: 'absolute',
            inset: 0,
            backgroundImage: `url(${afterImage})`,
            backgroundSize: 'cover',
            backgroundPosition: 'center',
            clipPath: `inset(0 ${clipRight}% 0 0)`,
          }}
        />

        <Box
          sx={{
            position: 'absolute',
            top: 12,
            left: 12,
            zIndex: 2,
            px: 1.25,
            py: 0.5,
            borderRadius: '999px',
            bgcolor: 'rgba(17, 24, 39, 0.82)',
            color: TOKENS.colors.textOnImage,
            fontSize: '0.6875rem',
            fontWeight: 700,
            letterSpacing: '0.12em',
            textTransform: 'uppercase',
          }}
        >
          Before
        </Box>

        <Box
          sx={{
            position: 'absolute',
            top: 12,
            right: 12,
            zIndex: 2,
            px: 1.25,
            py: 0.5,
            borderRadius: '999px',
            bgcolor: TOKENS.colors.violet,
            color: '#FFFFFF',
            fontSize: '0.6875rem',
            fontWeight: 700,
            letterSpacing: '0.12em',
            textTransform: 'uppercase',
          }}
        >
          After
        </Box>

        <Box
          aria-hidden
          sx={{
            position: 'absolute',
            top: 0,
            bottom: 0,
            left: `${position}%`,
            width: '2px',
            transform: 'translateX(-50%)',
            bgcolor: '#FFFFFF',
            zIndex: 3,
            boxShadow: '0 0 12px rgba(0,0,0,0.25)',
          }}
        />

        <Box
          role="slider"
          aria-label={`Compare before and after for ${name}`}
          aria-valuemin={0}
          aria-valuemax={100}
          aria-valuenow={Math.round(position)}
          onPointerDown={(event) => {
            event.stopPropagation();
            startDrag(event);
          }}
          sx={{
            position: 'absolute',
            top: '50%',
            left: `${position}%`,
            transform: 'translate(-50%, -50%)',
            zIndex: 4,
            width: 40,
            height: 40,
            borderRadius: '50%',
            bgcolor: '#FFFFFF',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            boxShadow: '0 4px 18px rgba(0,0,0,0.22)',
            cursor: 'ew-resize',
          }}
        >
          <HandleIcon />
        </Box>
      </Box>

      <Box id={id} sx={{ pt: 2 }}>
        <Typography
          sx={{
            fontFamily: TOKENS.fonts.display,
            fontWeight: 700,
            fontSize: TOKENS.typography.h3,
            color: TOKENS.colors.textPrimary,
            mb: 1,
            letterSpacing: '-0.02em',
          }}
        >
          {name}
        </Typography>

        <Box
          component="span"
          sx={{
            display: 'inline-flex',
            px: 1.5,
            py: 0.5,
            mb: 1,
            borderRadius: '999px',
            bgcolor: TOKENS.glow.purple,
            color: TOKENS.colors.purpleDeep,
            fontSize: TOKENS.typography.caption,
            fontWeight: 700,
          }}
        >
          {result}
        </Box>

        <Typography
          sx={{
            color: TOKENS.colors.textMuted,
            fontSize: TOKENS.typography.caption,
            lineHeight: 1.5,
          }}
        >
          {meta}
        </Typography>
      </Box>
    </Box>
  );
};

export default BeforeAfterCard;
