import { Box } from '@mui/material';
import { TOKENS } from '../../tokens';

const FlexContainer = ({ children, sx = {}, as: Component = 'div', ...rest }) => (
  <Box
    component={Component}
    sx={{
      width: '100%',
      maxWidth: TOKENS.layout.maxWidth,
      mx: 'auto',
      px: {
        xs: `${TOKENS.layout.gutter.xs}px`,
        sm: `${TOKENS.layout.gutter.sm}px`,
        lg: `${TOKENS.layout.gutter.lg}px`,
      },
      display: 'flex',
      flexDirection: 'column',
      ...sx,
    }}
    {...rest}
  >
    {children}
  </Box>
);

export const FlexRow = ({ children, sx = {}, wrap = true, ...rest }) => (
  <Box
    sx={{
      display: 'flex',
      flexDirection: 'row',
      flexWrap: wrap ? 'wrap' : 'nowrap',
      width: '100%',
      ...sx,
    }}
    {...rest}
  >
    {children}
  </Box>
);

export const FlexCol = ({ children, sx = {}, flex, grow, ...rest }) => (
  <Box
    sx={{
      display: 'flex',
      flexDirection: 'column',
      ...(flex !== undefined && { flex }),
      ...(grow && { flexGrow: 1 }),
      ...sx,
    }}
    {...rest}
  >
    {children}
  </Box>
);

export default FlexContainer;
